const s = items[0].json;
const today = new Date().toLocaleDateString();
const report = `DAILY PIPELINE REPORT — ${today}
=====================================

PROJECT PIPELINE
  New (unprocessed):     ${s.new}
  Qualified:             ${s.qualified}
  Enriched (w/ contact): ${s.enriched}
  Drafted:               ${s.drafted}
  Rejected:              ${s.rejected}

OUTREACH
  Emails sent:           ${s.emails_sent}
  Drafts pending review: ${s.drafts_pending}

REPLIES NEEDING ATTENTION
  Interested:            ${s.interested}
  Questions:             ${s.questions}

CRM & COMPLIANCE
  Contacts in CRM:       ${s.crm_contacts}
  Suppressed (opt-out):  ${s.suppressed}

=====================================
Hot opportunities: ${Number(s.interested) + Number(s.questions)} replies need a human follow-up today.`;

return [{ json: { report } }];
